SELECT t.title, n.name, cn.name, COUNT(*)
FROM title as t, movie_keyword as mk, keyword as k, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, non_leaf_686
WHERE mc.movie_id = mk.movie_id AND (n.name_pcode_cf ILIKE '%v65%') AND (rt.role IN ('cinematographer','composer','costume designer','director','editor','miscellaneous crew','producer','production designer','writer')) AND (t.title ILIKE '%pa%') AND mc.movie_id = non_leaf_686.t_id AND (cn.name ILIKE '%hol%') AND (kt.kind IN ('movie','tv movie','video game','video movie')) AND mc.movie_id = non_leaf_686.ci_movie_id AND mk.movie_id = non_leaf_686.t_id AND cn.id = mc.company_id AND mk.movie_id = non_leaf_686.ci_movie_id AND k.id = mk.keyword_id AND ct.id = mc.company_type_id;